318	function bfsPath(fromIdx: number, toIdx: number, allowed: Uint8Array): number[] | null {
319	  if (!allowed[fromIdx] || !allowed[toIdx]) return null;
320	  const prev = new Int32Array(nodes.length).fill(-1);
321	  const seen = new Uint8Array(nodes.length);
322	  const queue = [fromIdx];
323	  seen[fromIdx] = 1;
324	  for (let qi = 0; qi < queue.length; qi++) {
325	    const cur = queue[qi];
326	    if (cur === toIdx) {
327	      const path: number[] = [];
328	      for (let n = cur; n !== -1; n = prev[n]) path.push(n);
329	      return path.reverse();
330	    }
331	    for (const nx of adjacency[cur]) {
332	      if (seen[nx] || !allowed[nx]) continue;
333	      seen[nx] = 1; prev[nx] = cur; queue.push(nx);
334	    }
335	  }
336	  return null;
337	}
338	/** Among ALL shortest same-endpoint routes, the one entering fewest covered cells. */
339	function leastSupportedShortestPath(fromIdx: number, toIdx: number, allowed: Uint8Array, cov: Uint8Array): number[] | null {
340	  if (!allowed[fromIdx] || !allowed[toIdx]) return null;
341	  const dist = new Int32Array(nodes.length).fill(-1);
342	  dist[fromIdx] = 0;
343	  const order: number[] = [fromIdx];
344	  for (let qi = 0; qi < order.length; qi++) {
345	    for (const nx of adjacency[order[qi]]) {
346	      if (dist[nx] !== -1 || !allowed[nx]) continue;
347	      dist[nx] = dist[order[qi]] + 1; order.push(nx);
348	    }
349	  }
350	  if (dist[toIdx] === -1) return null;
351	  const dp = new Int32Array(nodes.length).fill(0x7fffffff);
352	  const from = new Int32Array(nodes.length).fill(-1);
353	  dp[fromIdx] = cov[fromIdx] ? 1 : 0;
354	  for (const n of order) {
355	    if (n === fromIdx || dist[n] > dist[toIdx]) continue;
356	    let bestCost = 0x7fffffff, bestPrev = -1;
357	    for (const p of adjacency[n]) {
358	      if (!allowed[p] || dist[p] !== dist[n] - 1 || dp[p] === 0x7fffffff) continue;
359	      const c = dp[p] + (cov[n] ? 1 : 0);
360	      if (c < bestCost || (c === bestCost && bestPrev !== -1 && (nodes[p].u < nodes[bestPrev].u
361	        || (nodes[p].u === nodes[bestPrev].u && nodes[p].v < nodes[bestPrev].v)))) { bestCost = c; bestPrev = p; }
362	    }
363	    if (bestPrev !== -1) { dp[n] = bestCost; from[n] = bestPrev; }
364	  }
365	  if (dp[toIdx] === 0x7fffffff) return null;
366	  const path: number[] = [];
367	  for (let n = toIdx; n !== -1; n = from[n]) path.push(n);
368	  return path.reverse();
369	}
370	function distanceToPolyline(p: THREE.Vector3, pts: THREE.Vector3[]): number {
371	  let best = Infinity;
372	  const ab = new THREE.Vector3(), ap = new THREE.Vector3();
373	  for (let i = 1; i < pts.length; i++) {
374	    const a = pts[i - 1], b = pts[i];
375	    ab.subVectors(b, a); ap.subVectors(p, a);
376	    const denom = ab.lengthSq();
377	    const t = denom < 1e-9 ? 0 : Math.max(0, Math.min(1, ap.dot(ab) / denom));
378	    best = Math.min(best, p.distanceTo(a.clone().addScaledVector(ab, t)));
