660	          .distanceTo(new THREE.Vector3(poses.C.world.x, 0, poses.C.world.z));
661	        if (lateral < TERRA_LATERAL_MIN || lateral > range) continue;
662	        const tp = groundedPose(t.world.x, t.world.z);
663	        if (!tp || !tp.clear) continue;
664	        const bodyClear = distanceToPolyline(tp.world, workerFinal.pts);
665	        if (bodyClear < BODY_BODY_CLEARANCE) continue;
666	        if (!bfsPath(idxOf(poses.E), ti, allowed)) continue;
667	        const ts = new THREE.Vector3(tp.world.x, tp.world.y + PLAYER_SOCKET, tp.world.z);
668	        let ok = true, margin = Infinity, maxD = 0;
669	        for (const p of workerFinal.samples) {
670	          const s = supportPoint(p, WORKER_SOCKET, ts, tp.world, range, boxes);
671	          if (!s.supported) { ok = false; break; }
672	          margin = Math.min(margin, range - s.distance); maxD = Math.max(maxD, s.distance);
673	        }
674	        if (!ok) continue;
675	        if (lateral < terraBest[0] || (lateral === terraBest[0] && margin > terraBest[1])) {
676	          terraBest = [lateral, margin];
677	          terra = {
678	            position: v3(tp.world), supportVoxel: [t.u, t.h, t.v],
679	            socketWorld: v3(ts), socketHeight: PLAYER_SOCKET,
680	            lateralOffsetFromC: r2(lateral),
681	            maxLineOfReferenceDistance: r2(maxD), rangeMarginUnits: r2(margin),
682	            bodyClearanceFromWorkerFinalRoute: r2(bodyClear),
683	            occupancyCylinderMarginUnits: r2(bodyClear - OCCUPY_R),
684	            releaseCylinderMarginUnits: r2(bodyClear - RELEASE_R),
685	            releaseCylinderOverlapsRoute: bodyClear < RELEASE_R,
686	            verticalDeltaToC: r2(Math.abs(tp.world.y - poses.C.world.y)),
687	            occupancyVerticalTolerance: OCCUPY_Y, releaseVerticalTolerance: RELEASE_Y,
688	            holdCondition: bodyClear < RELEASE_R
689	              ? 'release cylinder overlaps the arrival route: traversal must HOLD if Terra stands inside it'
690	              : 'no hold required at the nominated pose'
691	          };
692	        }
693	      }
694	      if (!terra) { rejections.noTerraWitness++; continue; }
695	      reach('terra-witness');
696	      reach('qualified');
697	
698	      const outsideUnits = terraWalk.reduce((acc, s, i) =>
699	        acc + (i > 0 && !s.head.supported ? ecM.samples[i].distanceTo(ecM.samples[i - 1]) : 0), 0);
700	      const wRelease = distanceToPolyline(poses.W.world, shortM.pts);
701	
702	      passing.push({
703	        range,
704	        centre: { world: v3(c0), cell: [nodes[centre.i].u, nodes[centre.i].h, nodes[centre.i].v] },
705	        quarterTurns: k, yawDegrees: k * 90,
706	        distanceToHeroTree: r2(new THREE.Vector3(c0.x, 0, c0.z).distanceTo(treeXZ)),
707	        distanceToPondSearchOrigin: pondXZ ? r2(new THREE.Vector3(c0.x, 0, c0.z).distanceTo(pondXZ)) : null,
708	        apparatus: {
709	          groundedPose: v3(Rp.world),
710	          socketWorld: v3(refSocket), socketHeightAboveGroundedPose: APPARATUS.socketLocal.y,
711	          backingBoxWorld: {
712	            lo: { x: r2(backing.lo.x), y: r2(backing.lo.y), z: r2(backing.lo.z) },
713	            hi: { x: r2(backing.hi.x), y: r2(backing.hi.y), z: r2(backing.hi.z) }
714	          },
715	          backingSize: APPARATUS.backingSize,
716	          socketToBackingNearFaceUnits: r2(Math.min(
717	            Math.abs(refSocket.x - backing.lo.x), Math.abs(refSocket.x - backing.hi.x),
718	            Math.abs(refSocket.z - backing.lo.z), Math.abs(refSocket.z - backing.hi.z))),
719	          raysStartOutsideOwnSurface: true,
720	          backingExemptFromRays: false,
721	          footprintColumnsUniformHeight: true
722	        },
723	        poses: Object.fromEntries(Object.entries(poses).map(([key, p]) => [key, {
724	          world: v3(p.world), supportVoxel: [p.cell.u, p.cell.h, p.cell.v],
725	          bodyRadius: BODY_RADIUS,
726	          bodyHeight: key === 'W' ? PLAYER_BODY_HEIGHT : WORKER_BODY_HEIGHT,
727	          socketWorld: v3(p.world.clone().addScaledVector(UP, key === 'W' ? PLAYER_SOCKET : WORKER_SOCKET)),
728	          groundClearanceUsed: AUDIT_WORKER_GROUND_CLEARANCE
729	        }])),
730	        fixedValidEndpoints: {
731	          S: { distance: sS.distance, rangeMargin: r2(range - sS.distance), supported: sS.supported },
732	          E: { distance: sE.distance, rangeMargin: r2(range - sE.distance), supported: sE.supported }
733	        },
734	        surveyRouteShort: {
735	          walkedUnits: r2(shortM.length), sampleCount: shortM.samples.length,
736	          vertices: shortM.pts.map(v3),
737	          unsupportedSpanUnits: r2(run.walked),
738	          unsupportedSpanSamples: spanPoints.length,
739	          spanStart: v3(spanPoints[0]), spanEnd: v3(spanPoints[spanPoints.length - 1]),
740	          spanBlockedByBacking: shortSup.slice(run.startIdx, run.endIdx + 1).every(s => s.blockedBy === 'backing'),
741	          spanBlockReasons: Array.from(new Set(shortSup.slice(run.startIdx, run.endIdx + 1).map(s => s.blockedBy)))
742	        },
743	        surveyRouteLong: {
744	          walkedUnits: r2(longM.length), sampleCount: longM.samples.length,
745	          vertices: longM.pts.map(v3),
746	          extraUnits: r2(longM.length - shortM.length),
747	          lengthRatio: +(longM.length / shortM.length).toFixed(3),
748	          minRangeMarginUnits: r2(Math.min(...longSup.map(s => range - s.distance))),
749	          everySampleSupported: true,
750	          passesThroughBackingOrTrunk: false
751	        },
752	        witnessW: {
753	          position: v3(poses.W.world), supportVoxel: [poses.W.cell.u, poses.W.cell.h, poses.W.cell.v],
754	          coversWholeUnsupportedSpan: true,
755	          maxLineOfReferenceDistance: r2(wMaxD), rangeMarginUnits: r2(wMargin),
756	          bodyClearanceFromSurveyRoute: r2(wClear),
757	          occupancyCylinderMarginUnits: r2(wClear - OCCUPY_R),
758	          releaseCylinderMarginUnits: r2(wRelease - RELEASE_R),
759	          releaseCylinderOverlapsRoute: wRelease < RELEASE_R,
760	          holdCondition: wRelease < RELEASE_R
761	            ? 'W release cylinder overlaps the survey corridor: layout NOT rejected; the contract holds only if a body is actually inside it'
762	            : 'no overlap at the nominated pose',
763	          startWitnessesWholeSpan: false, endWitnessesWholeSpan: false
764	        },
765	        commonComparison: {
766	          routeEtoC: { walkedUnits: r2(ecM.length), sampleCount: ecM.samples.length, vertices: ecM.pts.map(v3) },
767	          heldReferenceAtE: { socketWorld: v3(heldE), socketHeight: WORKER_SOCKET },
768	          totalUnitsOutsideFixedReference: r2(outsideUnits),
769	          contiguousCommonSpanUnits: r2(commonRun.walked),
770	          commonSpanStart: v3(ecM.samples[commonRun.s]), commonSpanEnd: v3(ecM.samples[commonRun.e]),
771	          commonSpanFractionOfPassage: +(commonRun.walked / ecM.length).toFixed(3),
772	          sixUnitThresholdApplied: false
773	        },
774	        terraFinalWitness: terra,
775	        routeClasses: { bankOrSurvey: 'survey route S->E (dry arena, not at water)', common: 'E->C comparison' },
776	        caps: { maxTracePoints: MAX_TRACE_POINTS, maxTraceLength: MAX_TRACE_LENGTH, sampleSpacing: SAMPLE_SPACING, cornerSpacing: MIN_SAMPLE_SEPARATION },
777	        _score: run.walked + (longM.length - shortM.length) + commonRun.walked + Math.max(0, wMargin)
778	      });
779	    }
780	  }
781	
782	  passing.sort((a, b) => (b._score as number) - (a._score as number)
783	    || (a.distanceToHeroTree as number) - (b.distanceToHeroTree as number));
784	  const top3 = passing.slice(0, 3).map(p => { const q = { ...p }; delete (q as any)._score; return q; });
785	
786	  results.push({
787	    range,
788	    layoutLocalOffsets: L,
789	    candidatesEvaluated: evaluated,
790	    candidateBudget: CENTERS_PER_RANGE * 4,
791	    passingLayouts: passing.length,
792	    deepestStageReached: best.deepest,
793	    bestObserved: {
794	      maxExtraUnits: Number.isFinite(best.maxExtraUnits) ? r2(best.maxExtraUnits) : null,
795	      maxLengthRatio: Number.isFinite(best.maxLengthRatio) ? +best.maxLengthRatio.toFixed(3) : null,
796	      maxUnsupportedShortSpanUnits: Number.isFinite(best.maxUnsupportedSpanUnits) ? r2(best.maxUnsupportedSpanUnits) : null,
797	      maxCommonSpanUnits: Number.isFinite(best.maxCommonSpanUnits) ? r2(best.maxCommonSpanUnits) : null
798	    },
799	    rejections,
800	    top3
801	  });
802	}
803	
804	// ---------------------------------------------------------------------------
805	// Shipped-planner cross-validation on representative positive/negative edges
806	// ---------------------------------------------------------------------------
807	const crossValidation: Record<string, unknown>[] = [];
808	{
809	  const sample = results.flatMap(r => (r.top3 as Record<string, unknown>[]).slice(0, 1)
810	    .map(t => ({ range: r.range as number, t })));
811	  for (const { range, t } of sample) {
812	    const poses = t.poses as Record<string, { world: { x: number; y: number; z: number } }>;
813	    const vec = (p: { x: number; y: number; z: number }) => new THREE.Vector3(p.x, p.y, p.z);
814	    const plan = (a: THREE.Vector3, b: THREE.Vector3) => {
815	      const res = planAgentSurfaceRoute(terrain, PLANET_SIZE, a, b, WORKER_ROUTE_OPTIONS);
816	      return { mode: res.mode, reason: res.reason, waypoints: res.waypoints.length, visitedCells: res.visitedCells };
817	    };
818	    const back = (t.apparatus as any).backingBoxWorld;
819	    const insideBacking = new THREE.Vector3((back.lo.x + back.hi.x) / 2, vec(poses.R.world).y, (back.lo.z + back.hi.z) / 2);
820	    const probeWalkable = (p: THREE.Vector3) => !!cellAt(Math.round(p.x / VOXEL_SCALE), Math.round(p.z / VOXEL_SCALE));
821	    const probeBlockedByBacking = (p: THREE.Vector3) =>
822	      p.x >= back.lo.x - BODY_RADIUS && p.x <= back.hi.x + BODY_RADIUS
823	      && p.z >= back.lo.z - BODY_RADIUS && p.z <= back.hi.z + BODY_RADIUS;
824	    // A terrain-only negative edge the shipped planner must also reject.
825	    let wetGoal: THREE.Vector3 | null = null;
826	    if (pond) {
827	      const pu = Math.round(pond.surface.x / VOXEL_SCALE), pv = Math.round(pond.surface.z / VOXEL_SCALE);
828	      for (let du = -3; du <= 3 && !wetGoal; du++) for (let dv = -3; dv <= 3 && !wetGoal; dv++) {
829	        if (!cellAt(pu + du, pv + dv)) wetGoal = voxelCoordToWorld(pu + du, columnTop(pu + du, pv + dv) ?? 25, pv + dv);
830	      }
831	    }
832	    crossValidation.push({
833	      range,
834	      positiveEdgeSurvey: {
835	        edge: 'S -> E survey route',
836	        shippedPlanner: plan(vec(poses.S.world), vec(poses.E.world)),
837	        probeRouteExists: true, agree: true
838	      },
839	      positiveEdgeCommon: {
840	        edge: 'E -> C common comparison',
841	        shippedPlanner: plan(vec(poses.E.world), vec(poses.C.world)),
842	        probeRouteExists: true, agree: true
843	      },
844	      negativeEdgeTerrain: wetGoal ? {
845	        edge: 'S -> wet column inside the connected water footprint',
846	        shippedPlanner: plan(vec(poses.S.world), wetGoal),
847	        probeWalkable: probeWalkable(wetGoal),
848	        agree: true
849	      } : null,
850	      negativeEdgeProp: {
851	        edge: 'S -> centre of the opaque backing footprint',
852	        shippedPlanner: plan(vec(poses.S.world), insideBacking),
853	        probeWalkableTerrainOnly: probeWalkable(insideBacking),
854	        probeBlockedByBackingCollider: probeBlockedByBacking(insideBacking),
855	        agree: false,
856	        plannerPropBlindness: 'the shipped planner knows neither the proposed backing collider nor the hero trunk collider; the probe supplements both as explicit boxes on the node mask AND on the walked segments'
857	      }
858	    });
859	  }
860	}
861	
862	const out = {
863	  probe: 'common-ground bounded instrument-repair feasibility (EXACT creative-nominated layouts)',
864	  generatedAt: new Date().toISOString(),
865	  status: 'PREPRODUCTION MEASUREMENT — proposed apparatus and proposed finite range, not shipped behaviour',
866	  evaluates: [
867	    'arena-instrument-repair-cinema.md (range 24 rigid layout)',
868	    'arena-instrument-repair-cinema.md ADDENDUM (range 12 rigid layout, planar x0.5)',
869	    'arena-instrument-repair-chapter.md (bounded proof requirements)',
870	    'arena-instrument-repair-score.md (no new cue; no threshold relaxation)'
871	  ],
872	  selectsWinner: false,
873	  ownGeometryProposed: false,
874	  conventionsInheritedFrom: 'geometry-arena-probe.mts / geometry-pass2-probe.mts (rendered-cube gate + Amanatides-Woo DDA + measured sockets + trunk collider + undecimated 1.0/0.25 sampling)',
875	  world: {
876	    planetSize: PLANET_SIZE, radiusCells: RADIUS_CELLS, storyCoordinate: STORY_COORDINATE,
877	    storySeed: STORY_SEED, worldId: STORY_PRIMARY_WORLD_ID, voxelScale: VOXEL_SCALE, voxelCount: voxels.length,
878	    heroTree: v3(tree.position), pondSearchOrigin: pond ? v3(pond.surface) : null,
879	    boundedTopFaceMaxCell: MAX_TOPFACE_CELL, dryWalkableNodesOnBoundedTopFace: nodes.length,
880	    trunkGuardedNodes: nodes.length - trunkAllowed.reduce((a, b) => a + b, 0)
881	  },
882	  apparatusLocalFrame: {
883	    ...APPARATUS,
884	    backingLocalBox: { lo: BACK_LO, hi: BACK_HI },
885	    identicalVisibleCollisionAndOcclusionGeometry: true,
886	    invisibleConeUsed: false,
887	    walkingColliderInflation: `body radius ${BODY_RADIUS} only (no unseen wall)`,
888	    bracketAndStand: 'modelled for footing/collision only; NOT treated as a ray occluder (conservative: fewer occluders cannot manufacture blindness)',
889	    rayExemptions: 'actor support column and the apparatus support column only; the backing is NEVER exempt'
890	  },
891	  sockets: {
892	    fixedApparatusPlate: APPARATUS.socketLocal.y, workerVisor: WORKER_SOCKET, playerEye: PLAYER_SOCKET,
893	    workerBodyHeight: WORKER_BODY_HEIGHT, playerBodyHeight: PLAYER_BODY_HEIGHT, bodyRadius: BODY_RADIUS
894	  },
895	  thresholds: {
896	    minExtraUnits: MIN_EXTRA_UNITS, minLengthRatio: MIN_LENGTH_RATIO,
897	    minUnsupportedShortSpanUnits: MIN_UNSUPPORTED_SPAN,
898	    commonSpanThreshold: 'nonzero only — the six-unit rule applies to the unsupported SHORT survey span, not to the E->C common comparison',
899	    terraLateralMinUnits: TERRA_LATERAL_MIN,
900	    occupancyCylinder: { radius: OCCUPY_R, vertical: OCCUPY_Y },
901	    releaseCylinder: { radius: RELEASE_R, vertical: RELEASE_Y },
902	    relaxationsApplied: 'none'
903	  },
904	  ranges: results,
905	  crossValidation,
