{
  const box = trunkBox(BODY_RADIUS);
  for (let i = 0; i < nodes.length; i++) {
    const c = nodes[i];
    if (c.world.x >= box.lo.x && c.world.x <= box.hi.x && c.world.z >= box.lo.z && c.world.z <= box.hi.z) trunkAllowed[i] = 0;
