// ---------------------------------------------------------------------------
// Graph helpers (verbatim conventions from geometry-arena-probe.mts)
// ---------------------------------------------------------------------------
function bfsPath(fromIdx: number, toIdx: number, allowed: Uint8Array): number[] | null {
  if (!allowed[fromIdx] || !allowed[toIdx]) return null;
