    if (n === fromIdx || dist[n] > dist[toIdx]) continue;
    let bestCost = 0x7fffffff, bestPrev = -1;
    for (const p of adjacency[n]) {
      if (!allowed[p] || dist[p] !== dist[n] - 1 || dp[p] === 0x7fffffff) continue;
      const c = dp[p] + (cov[n] ? 1 : 0);
