        || (nodes[p].u === nodes[bestPrev].u && nodes[p].v < nodes[bestPrev].v)))) { bestCost = c; bestPrev = p; }
    }
    if (bestPrev !== -1) { dp[n] = bestCost; from[n] = bestPrev; }
  }
