// ---------------------------------------------------------------------------
// Per-range bounded evaluation of the EXACT nominated layout
// ---------------------------------------------------------------------------
// Candidate centres: dry nodes nearest the existing hero tree (search origin).
const treeXZ = new THREE.Vector3(tree.position.x, 0, tree.position.z);
