const centreOrder = nodes
  .map((c, i) => ({ i, d: new THREE.Vector3(c.world.x, 0, c.world.z).distanceTo(treeXZ) }))
  .filter(e => trunkAllowed[e.i])
  .sort((a, b) => a.d - b.d || nodes[a.i].u - nodes[b.i].u || nodes[a.i].v - nodes[b.i].v)
