  const seen = new Uint8Array(nodes.length);
  const queue = [fromIdx];
  seen[fromIdx] = 1;
  for (let qi = 0; qi < queue.length; qi++) {
    const cur = queue[qi];
    if (cur === toIdx) {
      const path: number[] = [];
      for (let n = cur; n !== -1; n = prev[n]) path.push(n);
      return path.reverse();
    }
    for (const nx of adjacency[cur]) {
